                continue;
            }

            // (i + j) 为偶数 -> Alice 操作
            if ((i + j) % 2 == 0) {
                int best = INT_MIN;

                // 向下走
                if (i + 1 < n) {
                    int score = (grid[i + 1][j] == '1' ? 1 : -1);
                    best = max(best, dp[i + 1][j] + score);
                }

                // 向右走
                if (j + 1 < m) {
                    int score = (grid[i][j + 1] == '1' ? 1 : -1);
                    best = max(best, dp[i][j + 1] + score);
                }

                dp[i][j] = best;
            }
            // (i + j) 为奇数 -> Bob 操作
            else {
                int best = INT_MAX;

